// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, dismissProjectOwnerReminder, createFieldGroup, dragFieldRowAndWaitForSave } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});

async function createCollectionWithSingleOptionalField(page, collectionName) {
    await page.getByRole("textbox", { name: "A unique table name..." }).fill(collectionName);
    await page.getByRole("button", { name: "arrow_forward" }).click();
    await page.getByRole("checkbox", { name: "check_box_outline_blank" }).nth(0).click();
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const responsePromise1 = page.waitForResponse("**/collections**");
    await page.getByRole("button", { name: "check" }).click();
    await responsePromise1;

    // Wait for network activities to finish
    await page.waitForTimeout(3000);
}

test('testUi', async ({ page }) => {
    test.setTimeout(278000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/admin/logout`);
    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    await page.goto(baseUrl);
    // Wait for network activities to finish
    await page.waitForTimeout(3000);


    const playwrightRequest0: Record<string, any> = {
        "email": "admin@example.com",
        "password": "admin"
    };

    await signIn(page, getValue(playwrightRequest0, "email"), getValue(playwrightRequest0, "password"));
    await dismissProjectOwnerReminder(page);
    await page.goto(`${baseUrl}/admin/settings/data-model/+`);
    // Wait for network activities to finish
    await page.waitForTimeout(3000);


    const playwrightRequest1: Record<string, any> = {"collection": `sr_group_order_${Date.now()}`};

    await createCollectionWithSingleOptionalField(page, getValue(playwrightRequest1, "collection"));

    const playwrightRequest2: Record<string, any> = {"field": "details"};

    await createFieldGroup(page, getValue(playwrightRequest2, "field"));

    // Drag the "status" row out of the top-level list and drop it inside the "details" group.
    await dragFieldRowAndWaitForSave(page, 360, 217, 600, 306, 30);

    // "status" is now rendered inside the nested group container rather than at the top level.
    await expect(page.locator('.field-grid.group')).toContainText('status');

    // Moving a field into a group also removes it from the top-level list, so setSort() runs for
    // the remaining top-level fields and the PR's "Field order saved" toast is shown here too.
    await expect(page.locator('.notification-item.success')).toContainText('Field order saved');

    // The save succeeded, so Directus' "Unexpected Error" dialog is not shown.
    await expect(page.getByText('Network Error')).toHaveCount(0);
});
